 private void insert(String table,Map<String,Object> row){var keys=new ArrayList<>(row.keySet());if(db.update("INSERT INTO "+table+" ("+String.join(",",keys)+") VALUES ("+String.join(",",Collections.nCopies(keys.size(),"?"))+")",keys.stream().map(row::get).toArray())!=1)throw new TenantAccessException(ErrorCode.REVISION_CONFLICT);}
